-- =====================================================================
-- DATABASE: db_project  |  UNKLAB SMARTCLINIC (AI-Powered UKESMAS)
-- Skema + data demo realistis (kunjungan 14 hari terakhir relatif terhadap CURDATE()).
-- PERHATIAN: berkas ini menghapus (DROP) dan membuat ulang seluruh tabel.
-- =====================================================================

CREATE DATABASE IF NOT EXISTS `db_project` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `db_project`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `mahasiswa`, `prescriptions`, `sick_leaves`, `medical_records`, `appointments_queue`, `medicine_stock_logs`, `medicines`, `patients_profile`, `ai_analytics_logs`, `health_articles`, `doctor_schedules`, `aktivitas_log`, `pengaturan`, `security_incidents`, `login_logs`, `audit_logs`, `user_sessions`, `users`;

CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `password` VARCHAR(255) NOT NULL,
  `nama_lengkap` VARCHAR(120) NOT NULL,
  `email` VARCHAR(150) NULL UNIQUE,
  `google_id` VARCHAR(100) NULL UNIQUE,
  `role` ENUM('superadmin','clinicadmin','medstaff','lecturer','student') NOT NULL DEFAULT 'student',
  `active_session_token` VARCHAR(128) NULL,
  `last_login_at` DATETIME NULL,
  `avatar` VARCHAR(255) DEFAULT 'default-avatar.png',
  `avatar_url` VARCHAR(255) NULL,
  `status` ENUM('active','inactive') NOT NULL DEFAULT 'active',
  `last_login` DATETIME NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `patients_profile` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NULL,
  `nim_nip` VARCHAR(30) NOT NULL UNIQUE,
  `nama` VARCHAR(120) NOT NULL,
  `tipe` ENUM('mahasiswa','dosen','staf') NOT NULL DEFAULT 'mahasiswa',
  `gender` ENUM('L','P') NOT NULL DEFAULT 'L',
  `tanggal_lahir` DATE NULL,
  `fakultas` VARCHAR(100) NULL,
  `prodi` VARCHAR(100) NULL,
  `no_hp` VARCHAR(25) NULL,
  `golongan_darah` VARCHAR(3) NULL,
  `riwayat_alergi` TEXT NULL,
  `penyakit_kronis` VARCHAR(255) NULL,
  `kontak_darurat` VARCHAR(255) NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX (`user_id`),
  CONSTRAINT `fk_pp_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `medicines` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `kode` VARCHAR(20) NOT NULL UNIQUE,
  `nama` VARCHAR(120) NOT NULL,
  `kategori` VARCHAR(80) NOT NULL,
  `satuan` VARCHAR(30) NOT NULL,
  `stok` INT NOT NULL DEFAULT 0,
  `stok_minimum` INT NOT NULL DEFAULT 10,
  `harga` INT NOT NULL DEFAULT 0,
  `tanggal_kedaluwarsa` DATE NULL,
  `lokasi_rak` VARCHAR(30) NULL,
  `indikasi` TEXT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX (`kategori`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `appointments_queue` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `queue_number` VARCHAR(10) NOT NULL,
  `queue_date` DATE NOT NULL,
  `patient_id` INT NOT NULL,
  `user_id` INT NULL,
  `complaint` TEXT NOT NULL,
  `triage_category` VARCHAR(60) NULL,
  `triage_json` LONGTEXT NULL,
  `status` ENUM('Menunggu','Dipanggil','Diperiksa','Selesai','Dibatalkan') NOT NULL DEFAULT 'Menunggu',
  `asal_lokasi` VARCHAR(150) NULL,
  `called_at` DATETIME NULL,
  `call_acknowledged` TINYINT(1) NOT NULL DEFAULT 0,
  `call_acknowledged_at` DATETIME NULL,
  `handled_by` INT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX (`queue_date`,`status`),
  INDEX (`patient_id`),
  CONSTRAINT `fk_q_patient` FOREIGN KEY (`patient_id`) REFERENCES `patients_profile`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `medical_records` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `queue_id` INT NULL,
  `patient_id` INT NOT NULL,
  `doctor_id` INT NULL,
  `tekanan_sistolik` SMALLINT NULL,
  `tekanan_diastolik` SMALLINT NULL,
  `suhu` DECIMAL(4,1) NULL,
  `detak_jantung` SMALLINT NULL,
  `respirasi` SMALLINT NULL,
  `saturasi_o2` SMALLINT NULL,
  `berat_badan` DECIMAL(5,1) NULL,
  `keluhan_utama` TEXT NULL,
  `anamnesis` TEXT NULL,
  `diagnosis` VARCHAR(255) NOT NULL,
  `kode_icd` VARCHAR(12) NULL,
  `kategori_penyakit` VARCHAR(60) NULL,
  `riwayat_alergi` TEXT NULL,
  `tindakan` TEXT NULL,
  `catatan` TEXT NULL,
  `visit_date` DATETIME NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX (`patient_id`),
  INDEX (`visit_date`),
  INDEX (`kategori_penyakit`),
  CONSTRAINT `fk_mr_patient` FOREIGN KEY (`patient_id`) REFERENCES `patients_profile`(`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_mr_queue` FOREIGN KEY (`queue_id`) REFERENCES `appointments_queue`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `prescriptions` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `record_id` INT NOT NULL,
  `medicine_id` INT NOT NULL,
  `jumlah` INT NOT NULL,
  `aturan_pakai` VARCHAR(255) NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX (`record_id`),
  INDEX (`medicine_id`),
  CONSTRAINT `fk_rx_record` FOREIGN KEY (`record_id`) REFERENCES `medical_records`(`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rx_med` FOREIGN KEY (`medicine_id`) REFERENCES `medicines`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sick_leaves` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `record_id` INT NULL,
  `patient_id` INT NOT NULL,
  `kode_verifikasi` VARCHAR(20) NOT NULL UNIQUE,
  `tanggal_mulai` DATE NOT NULL,
  `tanggal_selesai` DATE NOT NULL,
  `jumlah_hari` SMALLINT NOT NULL DEFAULT 1,
  `alasan` VARCHAR(255) NULL,
  `issued_by` INT NULL,
  `status` ENUM('Aktif','Dicabut') NOT NULL DEFAULT 'Aktif',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX (`patient_id`),
  CONSTRAINT `fk_sl_patient` FOREIGN KEY (`patient_id`) REFERENCES `patients_profile`(`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_sl_record` FOREIGN KEY (`record_id`) REFERENCES `medical_records`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `medicine_stock_logs` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `medicine_id` INT NOT NULL,
  `tipe` ENUM('Masuk','Keluar','Penyesuaian') NOT NULL,
  `jumlah` INT NOT NULL,
  `stok_sebelum` INT NOT NULL,
  `stok_sesudah` INT NOT NULL,
  `referensi_id` INT NULL,
  `keterangan` VARCHAR(255) NULL,
  `user_id` INT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX (`medicine_id`),
  INDEX (`created_at`),
  CONSTRAINT `fk_sl_med` FOREIGN KEY (`medicine_id`) REFERENCES `medicines`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ai_analytics_logs` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `jenis` VARCHAR(30) NOT NULL,
  `input_summary` VARCHAR(500) NULL,
  `output_json` LONGTEXT NULL,
  `model` VARCHAR(60) NULL,
  `sumber` VARCHAR(20) NULL,
  `user_id` INT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX (`jenis`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `health_articles` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `judul` VARCHAR(200) NOT NULL,
  `slug` VARCHAR(220) NOT NULL UNIQUE,
  `kategori` VARCHAR(60) NOT NULL,
  `ringkasan` VARCHAR(400) NULL,
  `isi` TEXT NOT NULL,
  `tags` VARCHAR(500) NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `doctor_schedules` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `hari` VARCHAR(10) NOT NULL,
  `jam_mulai` VARCHAR(5) NOT NULL,
  `jam_selesai` VARCHAR(5) NOT NULL,
  `nama_tenaga` VARCHAR(120) NOT NULL,
  `peran` VARCHAR(80) NOT NULL,
  `lokasi` VARCHAR(80) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `pengaturan` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `setting_key` VARCHAR(50) NOT NULL UNIQUE,
  `setting_value` TEXT NULL,
  `deskripsi` VARCHAR(255) NULL,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `aktivitas_log` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NULL,
  `username` VARCHAR(50) NULL,
  `aktivitas` VARCHAR(100) NOT NULL,
  `detail` TEXT NULL,
  `ip_address` VARCHAR(45) NULL,
  `user_agent` TEXT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX (`user_id`),
  INDEX (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `security_incidents` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `incident_type` VARCHAR(60) NOT NULL,
  `source_ip` VARCHAR(45) NULL,
  `request_uri` VARCHAR(500) NULL,
  `payload_snippet` VARCHAR(600) NULL,
  `action_taken` VARCHAR(60) NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `login_logs` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` VARCHAR(50) NULL,
  `identifier_input` VARCHAR(120) NULL,
  `role` VARCHAR(30) NULL,
  `ip_address` VARCHAR(45) NULL,
  `user_agent` VARCHAR(255) NULL,
  `status` VARCHAR(20) NULL,
  `failure_reason` VARCHAR(255) NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `audit_logs` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `action` VARCHAR(100) NOT NULL,
  `target_table` VARCHAR(60) NULL,
  `record_id` VARCHAR(50) NULL,
  `description` TEXT NULL,
  `user_id` VARCHAR(50) NULL,
  `user_name` VARCHAR(120) NULL,
  `role` VARCHAR(30) NULL,
  `ip_address` VARCHAR(45) NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `user_sessions` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `session_id` VARCHAR(128) NOT NULL UNIQUE,
  `user_id` VARCHAR(50) NULL,
  `identifier` VARCHAR(120) NULL,
  `full_name` VARCHAR(120) NULL,
  `role` VARCHAR(30) NULL,
  `ip_address` VARCHAR(45) NULL,
  `user_agent` VARCHAR(255) NULL,
  `device_type` VARCHAR(20) NULL,
  `last_activity` INT NOT NULL DEFAULT 0,
  `is_revoked` TINYINT NOT NULL DEFAULT 0,
  `revoked_by` VARCHAR(120) NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;















SET FOREIGN_KEY_CHECKS = 1;
