INSERT INTO `health_articles` (`id`,`judul`,`slug`,`kategori`,`ringkasan`,`isi`,`tags`) VALUES
(1,'Panduan Pertolongan Pertama pada Demam','panduan-pertolongan-pertama-pada-demam','P3K','Demam bukan penyakit, melainkan tanda tubuh melawan infeksi. Atasi dengan kompres hangat dan hidrasi.','Demam adalah peningkatan suhu tubuh di atas 37,5 derajat Celsius. Lakukan kompres hangat pada dahi, ketiak, dan lipat paha, perbanyak minum air putih, kenakan pakaian tipis, dan istirahat. Paracetamol 500 mg dapat diminum 3x sehari bila suhu di atas 38. Segera ke UKESMAS bila demam lebih dari 3 hari, suhu di atas 39,5, disertai kejang, ruam, atau sesak napas.','demam,panas,meriang,menggigil,suhu,badan panas,kompres'),
(2,'Mengenali dan Mengatasi ISPA (Batuk Pilek)','mengenali-dan-mengatasi-ispa-batuk-pilek','Penyakit Umum','ISPA menular cepat di lingkungan kampus; kenali gejala dan cegah penularan dengan masker.','ISPA ditandai batuk, pilek, bersin, nyeri tenggorokan, dan kadang demam ringan. Penularan melalui percikan batuk, sehingga disarankan memakai masker, menjaga ventilasi ruangan, tidak berbagi gelas, dan mencuci tangan. Minum air hangat, istirahat, dan vitamin C membantu pemulihan. Periksakan ke klinik bila batuk lebih dari 7 hari, sesak, atau demam tinggi.','ispa,batuk,pilek,flu,bersin,tenggorokan,hidung tersumbat,masker'),
(3,'Maag dan Gastritis saat Musim Ujian','maag-dan-gastritis-saat-musim-ujian','Penyakit Umum','Telat makan, kopi berlebihan, dan stres ujian memicu kekambuhan maag.','Gastritis muncul sebagai nyeri atau perih ulu hati, mual, kembung, dan cepat kenyang. Pemicunya telat makan, kopi, makanan pedas dan asam, serta stres ujian. Makan porsi kecil tapi sering, hindari berbaring setelah makan, dan batasi kopi. Antasida diminum sebelum makan. Segera periksa bila muntah darah, BAB hitam, atau nyeri sangat hebat.','maag,gastritis,perut perih,ulu hati,asam lambung,kembung,mual,telat makan,ujian,perut sakit'),
(4,'Cara Mengatasi Diare dan Mencegah Dehidrasi','cara-mengatasi-diare-dan-mencegah-dehidrasi','Penyakit Umum','Oralit adalah kunci utama; waspadai tanda dehidrasi.','Diare adalah BAB cair lebih dari 3 kali sehari. Gantilah cairan dengan oralit atau air garam gula, makan makanan lunak, hindari pedas dan berminyak. Tanda dehidrasi: mulut kering, mata cekung, urin sedikit, lemas. Segera ke klinik bila ada darah dalam tinja, demam tinggi, atau diare lebih dari 2 hari.','diare,mencret,bab cair,dehidrasi,oralit,mules,sakit perut'),
(5,'Sakit Kepala: Kapan Cukup Istirahat dan Kapan ke Dokter','sakit-kepala-kapan-cukup-istirahat-dan-kapan-ke-dokter','Penyakit Umum','Sebagian besar sakit kepala tegang bisa diatasi mandiri; kenali tanda bahaya.','Sakit kepala tegang dipicu kurang tidur, stres, dan lama menatap layar. Istirahat, kompres, minum air cukup, dan atur jadwal tidur. Segera periksa bila sakit kepala mendadak sangat hebat, disertai kelemahan anggota gerak, bicara pelo, muntah menyemprot, atau penurunan kesadaran.','sakit kepala,pusing,migrain,cephalgia,kepala berdenyut,begadang'),
(6,'P3K Luka Lecet, Luka Sayat, dan Terkilir','p3k-luka-lecet-luka-sayat-dan-terkilir','P3K','Bersihkan luka, hentikan perdarahan, tutup dengan kasa steril.','Cuci luka dengan air mengalir dan sabun lembut, tekan dengan kasa bersih untuk menghentikan darah, beri antiseptik, lalu tutup. Untuk terkilir gunakan prinsip RICE: Rest, Ice, Compression, Elevation. Ke klinik bila luka dalam, kotor, perdarahan tidak berhenti, atau tulang dicurigai patah.','luka,lecet,sayat,terkilir,keseleo,jatuh,cedera,perdarahan,p3k,antiseptik'),
(7,'Tanda Gawat Darurat yang Harus Segera ke IGD','tanda-gawat-darurat-yang-harus-segera-ke-igd','Darurat','Nyeri dada, sesak berat, pingsan, kejang, dan perdarahan hebat butuh penanganan segera.','Segera hubungi petugas atau ke IGD terdekat bila terjadi nyeri dada menjalar, sesak napas berat, pingsan atau penurunan kesadaran, kejang, muntah darah, perdarahan hebat, lumpuh sebagian badan, atau reaksi alergi berat dengan bengkak wajah. Hubungi satpam kampus untuk bantuan transportasi darurat.','darurat,igd,nyeri dada,sesak,pingsan,kejang,perdarahan,muntah darah,alergi berat,ambulans'),
(8,'Prosedur Berobat Mahasiswa UNKLAB','prosedur-berobat-mahasiswa-unklab','Prosedur','Alur: konsultasi AI, ambil antrean online, pemeriksaan, resep, dan surat sakit.','Mahasiswa login ke SmartClinic, menuliskan keluhan pada halaman Konsultasi AI, lalu mengambil nomor antrean online. Nomor antrean dilayani berurutan (A-001, A-002, dst.). Datang ke UKESMAS saat nomor dipanggil. Setelah pemeriksaan, dokter menerbitkan resep digital dan, bila perlu, Surat Keterangan Sakit ber-kode verifikasi untuk dosen. Untuk keadaan darurat di luar jam operasional, segera hubungi petugas keamanan kampus atau IGD terdekat.','prosedur,berobat,antrean,daftar,mahasiswa,alur,cara berobat'),
(9,'Surat Keterangan Sakit Digital dan Verifikasi oleh Dosen','surat-keterangan-sakit-digital-dan-verifikasi-oleh-dosen','Prosedur','Setiap surat memiliki kode unik dan QR yang dapat diverifikasi dosen.','Surat Keterangan Sakit diterbitkan dokter UKESMAS setelah pemeriksaan. Setiap surat memuat kode verifikasi unik dan QR. Dosen dapat memverifikasi keabsahan di menu Verifikasi Surat Sakit dengan memasukkan kode atau memindai QR. Surat tidak memuat diagnosis demi menjaga kerahasiaan medis mahasiswa.','surat sakit,izin sakit,sks,verifikasi,qr,dosen,absen,izin kuliah'),
(10,'Menjaga Kesehatan Selama Masa Ujian','menjaga-kesehatan-selama-masa-ujian','Gaya Hidup','Tidur cukup, makan teratur, dan hidrasi menjaga stamina saat ujian.','Tidur 7-8 jam, makan tiga kali sehari tepat waktu, batasi kopi dan minuman energi, dan sisipkan olahraga ringan. Konsumsi buah, sayur, dan vitamin sesuai anjuran. Hindari makan mi instan berlebihan. Segera konsultasi bila mengalami cemas berlebihan atau gangguan tidur berkepanjangan.','ujian,stamina,tidur,begadang,kopi,stres,gizi,vitamin,belajar'),
(11,'Alergi Kulit dan Biduran: Penanganan Awal','alergi-kulit-dan-biduran-penanganan-awal','Penyakit Umum','Kenali pemicu alergi dan hindari; antihistamin membantu mengurangi gatal.','Alergi kulit muncul sebagai ruam merah, gatal, dan biduran. Hindari pemicu (makanan laut, sabun baru, debu). Kompres dingin dan jangan digaruk. Antihistamin seperti cetirizine dapat diberikan sesuai anjuran. Segera ke IGD bila disertai sesak napas atau bengkak pada wajah.','alergi,gatal,biduran,ruam,kulit,seafood,dermatitis,cetirizine'),
(12,'Asma Ringan: Mengenali Serangan dan Penanganan Awal','asma-ringan-mengenali-serangan-dan-penanganan-awal','Penyakit Umum','Penderita asma sebaiknya membawa obat pereda dan menghindari pemicu.','Serangan asma ditandai sesak, mengi, dan batuk malam hari. Duduk tegak, tenangkan diri, gunakan obat pereda sesuai petunjuk dokter, dan hindari debu serta asap. Segera ke klinik bila obat tidak membantu atau bibir membiru.','asma,sesak,mengi,napas,salbutamol,bronkodilator'),
(13,'Kebersihan dan Pencegahan Penyakit Menular di Kampus','kebersihan-dan-pencegahan-penyakit-menular-di-kampus','Gaya Hidup','Kebersihan ruangan, ventilasi, dan cuci tangan menurunkan angka penularan.','Bersihkan kamar dan ruang belajar secara rutin, buka jendela agar sirkulasi udara baik, jangan berbagi alat makan, serta cuci tangan dengan sabun sebelum makan. Gunakan masker bila sedang batuk atau pilek agar tidak menularkan kepada teman.','kebersihan,pencegahan,cuci tangan,ventilasi,menular,hygiene'),
(14,'Mengenali Dehidrasi dan Kelelahan Panas','mengenali-dehidrasi-dan-kelelahan-panas','Gaya Hidup','Minum cukup air terutama saat beraktivitas di luar ruangan.','Tanda dehidrasi ringan adalah haus, mulut kering, pusing, dan urin pekat. Minum air secara bertahap, istirahat di tempat teduh, dan konsumsi oralit bila perlu. Cari pertolongan bila pingsan atau kebingungan.','dehidrasi,haus,lelah,panas,pusing,minum,oralit,olahraga'),
(15,'Obat Bebas yang Aman untuk Keluhan Ringan','obat-bebas-yang-aman-untuk-keluhan-ringan','Obat','Pahami fungsi dan aturan obat bebas sebelum dikonsumsi.','Paracetamol untuk demam dan nyeri, antasida untuk maag ringan, oralit untuk diare, CTM untuk alergi (menimbulkan kantuk), dan OBH untuk batuk. Baca aturan pakai, perhatikan riwayat alergi, dan jangan menggunakan antibiotik tanpa resep dokter. Tanyakan apoteker UKESMAS bila ragu.','obat,paracetamol,antasida,ctm,obh,antibiotik,apotek,aturan pakai,dosis');
